import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Seats","description":"How seats for editing rights work in ApptiveGrid and when they run low.","frontmatter":{"title":"Seats","description":"How seats for editing rights work in ApptiveGrid and when they run low."},"headers":[],"relativePath":"en/zusammenarbeit/sitzplaetze.md","filePath":"en/zusammenarbeit/sitzplaetze.md","lastUpdated":1787319236000}'),n={name:"en/zusammenarbeit/sitzplaetze.md"};function i(r,e,l,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="seats" tabindex="-1">Seats <a class="header-anchor" href="#seats" aria-label="Permalink to &quot;Seats&quot;">​</a></h1><p>A <strong>seat</strong> is a license for one person with editing rights in a Space.</p><h2 id="the-basic-rule" tabindex="-1">The basic rule <a class="header-anchor" href="#the-basic-rule" aria-label="Permalink to &quot;The basic rule&quot;">​</a></h2><blockquote><p><em>The owner can purchase additional seats for users with editing rights. Read-only access is free.</em></p></blockquote><p>Specifically:</p><table tabindex="0"><thead><tr><th>Role</th><th style="text-align:center;">Occupies a seat</th></tr></thead><tbody><tr><td><strong>Read only</strong></td><td style="text-align:center;">no</td></tr><tr><td><strong>Edit entries</strong></td><td style="text-align:center;">yes</td></tr><tr><td><strong>Manage</strong></td><td style="text-align:center;">yes</td></tr><tr><td><strong>Owner</strong></td><td style="text-align:center;">yes</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Unlimited readers</p><p>You can add as many people with the <em>Read only</em> role to a Space as you like, without using up seats. For stakeholders, customers, or adjacent departments who only need to follow along, this is the right approach.</p></div><h2 id="checking-available-seats" tabindex="-1">Checking available seats <a class="header-anchor" href="#checking-available-seats" aria-label="Permalink to &quot;Checking available seats&quot;">​</a></h2><p>Open <strong>Space settings → General</strong>. There it says:</p><blockquote><p><em>Available seats for users with editing rights:</em></p></blockquote><p>Via <strong>Adjust seats</strong>, the owner changes the number.</p><div class="warning custom-block"><p class="custom-block-title">Seats apply per Space</p><p>The count is tied to the individual Space, not the account. If you work with several Spaces, each has its own seats.</p></div><h2 id="when-seats-aren-t-enough" tabindex="-1">When seats aren&#39;t enough <a class="header-anchor" href="#when-seats-aren-t-enough" aria-label="Permalink to &quot;When seats aren&#39;t enough&quot;">​</a></h2><p>If you invite more people with editing rights than there are seats available, ApptiveGrid reports:</p><blockquote><p><strong>Exceeded the licensed seats in your plan</strong></p><p><em>It looks like you&#39;ve invited more users than you have licensed seats for.</em></p><p><em>You need {number} more seats.</em></p><p><em>Change users&#39; permissions to &quot;Read only&quot; or book additional seats.</em></p></blockquote><p>Two ways out of this:</p><p><strong>1. Downgrade roles.</strong> Go through the <em>Shared with</em> list and set everyone who doesn&#39;t really need to edit to <strong>Read only</strong>. This is free and takes effect immediately.</p><p><strong>2. Book more seats.</strong> Via <em>Adjust seats</em> in the Space settings. Only the owner can do this.</p><div class="tip custom-block"><p class="custom-block-title">Clean up first, then book</p><p>Experience shows that in Spaces that have grown over time, more people have editing rights than they actually need — often because it wasn&#39;t considered at invitation time. Reviewing the roles list is usually cheaper than buying extra seats.</p><p>Also think about people who&#39;ve left: anyone who no longer needs the Space should be removed entirely.</p></div><h2 id="who-doesn-t-need-a-seat" tabindex="-1">Who doesn&#39;t need a seat <a class="header-anchor" href="#who-doesn-t-need-a-seat" aria-label="Permalink to &quot;Who doesn&#39;t need a seat&quot;">​</a></h2><p>A common misunderstanding: not everyone who works with your data needs a seat.</p><table tabindex="0"><thead><tr><th>This person …</th><th>Needs a seat?</th></tr></thead><tbody><tr><td>fills in a public form</td><td>no — no account needed</td></tr><tr><td>fills in a form restricted to the Space</td><td>no — the <em>Read only</em> role is enough</td></tr><tr><td>views a shared view via a link</td><td>no</td></tr><tr><td>uses a published portal</td><td>no</td></tr><tr><td>reads data in the Space</td><td>no — <em>Read only</em> role</td></tr><tr><td>changes entries in the Space</td><td><strong>yes</strong></td></tr><tr><td>builds forms, views, or Flows</td><td><strong>yes</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Data collection without seats</p><p>If many people need to regularly submit data without working in the Space itself, a <strong>form</strong> is almost always the right solution — not an invitation. Forms don&#39;t cost seats, no matter how many people fill them in.</p></div><h2 id="trial-period" tabindex="-1">Trial period <a class="header-anchor" href="#trial-period" aria-label="Permalink to &quot;Trial period&quot;">​</a></h2><p>New Spaces start with a trial period. The Space settings show:</p><blockquote><p><em>Trial period days remaining:</em></p></blockquote><p>During the trial period, extended features are available. After that, the limits of the booked plan apply.</p><div class="warning custom-block"><p class="custom-block-title">Settings can disappear after the trial period</p><p>When the trial period ends, or a plan is downgraded, ApptiveGrid removes settings that aren&#39;t included in the lower plan — particularly for forms.</p><p>Before switching, note down which paid features you&#39;re using, so you don&#39;t discover the loss only while working live.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/rollen">Roles</a></li><li><a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></li><li><a href="/en/spaces/einstellungen">Space settings</a> — adjust seats</li></ul>',30)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
